INSERT INTO `tmp_548_creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(1410,0,0,'You won\'t escape alive!',12,0,100,0,0,0,'Firewing Bloodwarder'),
(1410,0,1,'I will have your energy and then your life!',12,0,100,0,0,0,'Firewing Bloodwarder'),
(5355,0,2,'You won\'t escape alive!',12,0,100,0,0,0,'Firewing Defender'),
(5355,0,3,'You know too much!',12,0,100,0,0,0,'Firewing Defender'),
(15402,0,0,'Such... dark... energy!  How can this be possible?',12,0,100,0,0,0,'Apprentice Mirveda'),
(15941,0,0,'What?  Oh, not this again!',12,0,100,0,0,0,''),
(15945,0,0,'You can\'t do this to me!  We had a deal!',12,0,100,0,0,0,''),
(15951,0,0,'Good riddance... now none shall be able to repeat my mistakes!',12,0,100,0,0,0,'Magister Duskwither'),
(16183,0,0,'Where... where am I?',12,0,100,0,0,0,'Courier Dawnstrider'),
(16196,0,0,'You\'re not going anywhere just yet, handsome.  Not until you regain your strength.',12,0,100,0,0,0,'Apothecary Thedra'),
(16514,0,0,'Tedon, go ahead and try the neutralizing agent on the mutated creature.',12,0,100,1,0,0,'Botanist Taerix'),
(16521,0,0,'I hope you\'ve made your peace.',12,0,100,0,0,0,'Blood Elf Scout'),
(16521,0,1,'We won\'t allow you to leave this valley!',12,0,100,0,0,0,'Blood Elf Scout'),
(16521,0,2,'What a pity you survived the crash just to die here.',12,0,100,0,0,0,'Blood Elf Scout'),
(16522,0,0,'You\'ll not take me alive, scum!',12,0,100,0,0,0,'Surveyor Candress'),
(16584,0,0,'I\'ve seen gnomes work harder than you, peon! Little girl gnomes - with pig tails! MOVE IT, MOVE IT, MOVE IT!',12,1,100,5,0,0,'Watch Commander Krunk'),
(16585,0,0,'Yer slop is ready. Come n\' get it...',12,1,100,0,0,0,'Cookie One-Eye'),
(16585,1,0,'And if I hear that you palookas complained to Nazgrel again, it\'ll be one of ya\'s that I serve up next time...',12,1,100,0,0,0,'Cookie One-Eye'),
(16590,0,0,'If my stomach wasn\'t threatening to dislodge itself from my body and leave me for the refuse that we give to the prisoners, I might be insulted by this... this food.',12,1,100,0,0,0,'Injured Thrallmar Grunt'),
(16590,0,1,'Do I detect a hint of cinnamon? Or is that nutmeg? Whatever it is, one thing\'s for sure - nobody cooks a donkey like you, Cookie.',12,1,100,0,0,0,'Injured Thrallmar Grunt'),
(16590,1,0,'What kinda orcs, chief?',12,1,100,0,0,0,'Injured Thrallmar Grunt'),
(16590,2,0,'You mean...',12,1,100,0,0,0,'Injured Thrallmar Grunt'),
(16590,3,0,'But how, chief? I thought the curse was lifted...\n',12,1,100,0,0,0,'Injured Thrallmar Grunt'),
(16769,0,0,'Knowing there isn\'t enough time, the %s doesn\'t even try to run.',16,0,100,0,0,0,'Firewing Warlock'),
(16769,1,0,'For Kael\'thas!',12,0,100,0,0,0,'Firewing Warlock'),
(16769,1,1,'You won\'t escape alive!',12,0,100,0,0,0,'Firewing Warlock'),
(16769,1,2,'Kill them before they get away!',12,0,100,0,0,0,'Firewing Warlock'),
(16769,1,3,'I will have your energy and then your life!',12,0,100,0,0,0,'Firewing Warlock'),
(16794,0,0,'...a potent concoction!',12,0,100,0,0,0,'Apothecary Azethen'),
(16794,1,0,'But where could I ever find a suitable test subject?',12,0,100,6,0,0,'Apothecary Azethen'),
(16794,2,0,'Drink this, you blue brute!  Disobey me and I promise you a slow, painful death!',12,0,100,25,0,0,'Apothecary Azethen'),
(16794,3,0,'Hmmm... looks like I\'m going to need a new test subject.',12,0,100,274,0,0,'Apothecary Azethen'),
(16795,0,0,'I pity you, Forsaken.  Your soul is devoid of light.',12,35,100,0,0,0,'Draenei Prisoner'),
(16802,0,0,'It was inevitable!',14,0,100,0,0,0,''),
(16802,0,1,'You die in vain!',14,0,100,0,0,0,''),
(16846,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Mag\'har Grunt'),
(16847,0,0,'My strength.... is... returning!',12,1,100,0,0,0,'Debilitated Maghar Grunt'),
(16847,0,1,'You\'ve found a cure!  We will crush our enemies!',12,1,100,0,0,0,'Debilitated Maghar Grunt'),
(16847,0,2,'You\'ve restored my health!  I\'m in your debt, $n.',12,1,100,0,0,0,'Debilitated Maghar Grunt'),
(16863,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Deranged Helboar'),
(16871,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Bleeding Hollow Grunt'),
(16876,0,0,'%s becomes unstable and begins to disintegrate!',16,0,100,0,0,0,'Bonechewer Mutant'),
(16938,0,0,'Put me out of this misery!',12,0,100,0,0,0,'Dreghood Brute'),
(16938,0,1,'Forgive me... I have no choice.',12,0,100,0,0,0,'Dreghood Brute'),
(16943,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Cyber-Rage Forgelord'),
(16964,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Warlord Morkh'),
(17015,0,0,'Another pilgrim has arrived! Bring water quickly, or we may lose her!',12,0,100,0,0,0,'Wounded Blood Elf Pilgrim'),
(17058,0,0,'Do not stop!  I promise you a thousand deaths if you even think about putting down that pick!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,0,1,'Dig faster, wretch!  Do not force me to show you the true meaning of pain!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,0,2,'Faster, scum!  The Master won\'t be pleased if we don\'t find the Ata\'mal crystal he\'s after.',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,1,0,'You dare interfere with the Master\'s endeavors?  You will pay, foolish mortal!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,1,1,'Slay these intruders, filthy Dreghood!  I promise you neverending pain if you disobey me!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,1,2,'Go, you little wretches!  Show these fools that our Master is not to be trifled with!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17058,1,3,'Do not even think of fleeing, Broken wretches!  I promise you a fate worse than death if you don\'t slay these intruders!',12,0,100,0,0,0,'Illidari Taskmaster'),
(17117,0,0,'%s groans.',16,7,100,0,0,0,'Injured Night Elf Priestess'),
(17117,1,0,'%s sits up.',16,7,100,0,0,0,'Injured Night Elf Priestess'),
(17117,2,0,'Whe... Where am I? What... What is this place?',12,7,100,6,0,0,'Injured Night Elf Priestess'),
(17117,3,0,'BY THE LIGHT OF ELUNE! Eredar! Cursed demons, what have you done to me? I have not come alone, we will fight you as we have in the past! I...',12,7,100,5,0,0,'Injured Night Elf Priestess'),
(17117,4,0,'%s falls back into a coma.',16,0,100,0,0,0,'Injured Night Elf Priestess'),
(17123,0,0,'Welcome, kind spirit.  What has brought you to us?',12,1,100,0,0,0,''),
(17156,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Tortured Earth Spirit'),
(17188,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Raving Owlbeast'),
(17214,0,0,'Now to apply the ointment to her wounds.',12,7,100,1,0,0,'Anchorite Fateema'),
(17214,1,0,'It appears that the ointment is ineffective. Such a pity...',12,7,100,1,0,0,'Anchorite Fateema'),
(17214,2,0,'Man\'ari... But how... We are not eredar! She must know! If there are others like her, we must find them and explain...',12,7,100,1,0,0,'Anchorite Fateema'),
(17215,0,0,'There may still be a solution. Come here, $n. I will explain what I need.',12,7,100,1,0,0,'Daedal0'),
(17215,1,0,'This should do it...',12,7,100,0,0,0,'Daedal'),
(17215,2,0,'Wake up little creature. Wake up from your slumber... You are safe now.',12,7,100,0,0,0,'Daedal'),
(17240,0,0,'Hey, Cookie! What\'s for dinner tonight? And don\'t say chicken!',12,7,100,22,0,0,'Admiral Odesyus'),
(17240,1,0,'Wow! Really?',12,7,100,5,0,0,'Admiral Odesyus'),
(17240,2,0,'I hate you so much, Cookie.',12,7,100,1,0,0,'Admiral Odesyus'),
(17241,0,0,'Adamant, could you please take a look at this tablet and try to decipher the runes?',12,7,100,1,0,0,'Priestess Kyleen Il\'dinare'),
(17241,1,0,'Thank you, Adamant. I think I know just the person for the job.',12,7,100,2,0,0,'Priestess Kyleen Il\'dinare'),
(17242,0,0,'Of course! Anything for you, darling!',12,7,100,5,0,0,'Archaeologist Adamant Ironheart'),
(17242,1,0,'Alright, let me take a look at that tablet.',12,7,100,1,0,0,'Archaeologist Adamant Ironheart'),
(17242,2,0,'%s slowly reads the tablet, mouthing the words in their native tongue.',16,7,100,0,0,0,'Archaeologist Adamant Ironheart'),
(17242,3,0,'Naga warlord! Oh dear...',12,7,100,5,0,0,'Archaeologist Adamant Ironheart'),
(17242,4,0,'Well, you aren\'t going to like what I have to tell you, young missy. This tablet is a naga communication. Their leader, Warlord Sriss\'tiz, has ordered his naga to take the rest of the island by force.',12,7,100,1,0,0,'Archaeologist Adamant Ironheart'),
(17242,5,0,'And it looks like he\'s got reinforcements comin\' from Nazjatar!',12,7,100,5,0,0,'Archaeologist Adamant Ironheart'),
(17242,6,0,'We\'ve got to do something about this!',12,0,100,5,0,0,'Archaeologist Adamant Ironheart'),
(17246,0,0,'Yarr, Admiral. Let me think about it... Arrr... It be comin\' into focus.',12,7,100,1,0,0,'"Cookie" McWeaksauce'),
(17246,1,0,'It looks like it be succulent pork ribs basted with its own delectable juices and a side o\' Captain Sander\'s Secret Sauce - fer dippin\'.',12,7,100,1,0,0,'"Cookie" McWeaksauce'),
(17246,2,0,'And fer dessert we be havin\' cheesecake, flown in fresh from Stormwind on the wings o\' angels...',12,7,100,1,0,0,'"Cookie" McWeaksauce'),
(17246,3,0,'No. Not really...',12,7,100,274,0,0,'"Cookie" McWeaksauce'),
(17246,4,0,'It be chicken...',12,7,100,1,0,0,'"Cookie" McWeaksauce'),
(17591,0,0,'Your money or your life! Actually, just your life will do...',12,0,100,0,0,0,'Blood Elf Bandit'),
(17591,0,1,'Your death will make a fitting tribute to the King!',12,0,100,0,0,0,'Blood Elf Bandit'),
(17591,0,2,'For Silvermoon! For Sunstrider!',12,0,100,0,0,0,'Blood Elf Bandit'),
(17664,0,0,'You will regret this, maggot.',12,0,100,0,0,0,'Matis the Cruel'),
(17664,1,0,'%s falls unconscious.',16,0,100,0,0,0,'Matis the Cruel'),
(17702,0,0,'Face the wrath of Bristlelimb!',14,0,100,0,0,0,'High Chief Bristlelimb'),
(17831,0,0,'$n, let\'s go see if this plan will work.  Come along, Buddy!',12,0,100,0,0,0,'Watcher Leesa\'oh'),
(17831,1,0,'Ok, let\'s see about using those mushrooms you brought back to grow the bog lords a new food supply.',12,0,100,0,0,0,'Watcher Leesa\'oh'),
(17831,2,0,'Wait and see what happens!',12,0,100,0,0,0,'Watcher Leesa\'oh'),
(17831,3,0,'Oh Buddy, you big baby!  Look, it\'s working.  It\'s really working!!  Now all I need to do is grow more of these mushrooms here and the bog lords will likely leave the sporelings alone!',12,0,100,0,0,0,'Watcher Leesa\'oh'),
(17831,4,0,'Oh, thank you, $n!  You\'ve made it possible to save both the sporelings from the bog lords, and the bog lords from our wrath.',12,0,100,0,0,0,'Watcher Leesa\'oh'),
(17877,0,0,'Fhwoor go now, $n.  Get ark, come back.',12,0,100,1,0,0,''),
(17877,1,0,'Take moment... get ready.',12,0,100,1,0,0,''),
(17877,2,0,'We go!',12,0,100,5,0,0,''),
(17877,3,0,'%s lifts the Ark of Ssslith with ease.',16,0,100,0,0,0,''),
(17877,4,0,'Uh oh...',12,0,100,1,0,0,''),
(17877,5,0,'Ha ha, squishy naga!',12,0,100,1,0,0,''),
(17877,6,0,'%s places the Ark of Ssslith on the ground.',16,0,100,0,0,0,''),
(17877,7,0,'Fhwoor do good!',12,0,100,5,0,0,''),
(17955,0,0,'The %s takes a piece of the mushroom tree and holds it to its \'nose\'.  Seemingly satisfied, it eats it!',16,0,100,36,0,0,'Hungry Bog Lord'),
(17955,1,0,'The %s uproots the rest of the mushroom tree and makes off with it.',16,0,100,36,0,0,'Hungry Bog Lord'),
(18062,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Enraged Crusher'),
(18098,0,0,'%s examines the information on the wanted poster.',16,0,100,0,0,0,'Kialon Nightblade'),
(18117,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Ango\'rosh Ogre'),
(18119,0,0,'%s becomes enraged!',16,0,100,0,0,0,'Ango\'rosh Brute'),
(18292,0,0,'I wanna be just like the pitfighter!',12,7,100,5,0,0,'Bleeding Hollow Refugee'),
(18292,0,1,'Will he win? Can he win?',12,7,100,5,0,0,'Bleeding Hollow Refugee'),
(18293,0,0,'He\'s so well disciplined!',12,7,100,21,0,0,'Sunspring Post Refugee'),
(18296,0,0,'How does he do it?',12,7,100,0,0,0,'Sunspring Post Orphan'),
(18296,0,1,'I wanna be just like the pitfighter!',12,7,100,0,0,0,'Sunspring Post Orphan'),
(18296,0,2,'Wow! Look at his muscles!',12,7,100,0,0,0,'Sunspring Post Orphan'),
(18303,0,0,'My brothers and sisters. Listen to me. We must speak of the survival of our people. We have narrowly survived one calamity, but I fear the next shall destroy us.',12,0,100,1,0,0,'Lyria Skystrider'),
(18303,1,0,'Can you not see what is happening? Open your eyes. It is laid bare for all to see. What is this new alliance? Why have we betrayed our allies of old, only to take up with the enemies of all that live?',12,0,100,1,0,0,'Lyria Skystrider'),
(18303,2,0,'You speak of her as friend? You are a fool. This "Dark Lady" is not Sylvanas.',12,0,100,1,0,0,'Lyria Skystrider'),
(18303,3,0,'Blood? And these orcs, these fair weather friends? They will aid us?',12,0,100,11,0,0,'Lyria Skystrider'),
(18303,4,0,'The magisters are the traitors! They have sealed our doom.',12,0,100,25,0,0,'Lyria Skystrider'),
(18303,5,0,'We have not struggled so hard to survive, only to bring about the true destruction.',12,0,100,1,0,0,'Lyria Skystrider'),
(18303,6,0,'If we speak as one, we cannot be ignored!',12,0,100,1,0,0,'Lyria Skystrider'),
(18303,7,0,'We will repay the betrayal of the Alliance! We shall never forget, and never forgive!',12,1,100,21,0,0,'Lyria Skystrider'),
(18337,0,0,'That should take care of that. Summon me if you have further need of my services.',12,0,100,11,0,0,'Priest Kath\'mar'),
(18385,0,0,'I never thought it would turn out to be mana oil! There\'s going to be plenty of demand for that, minus Grek, of course!',12,0,100,0,0,0,'Rakoria'),
(18385,1,0,'Ship it!',12,0,100,25,0,0,'Rakoria'),
(18407,0,0,'Damn those ogres. Damn them to the Nether. Won\'t someone save us from these savages! This is the fifth kidnapping in as many days.',12,1,100,0,0,0,'Warden Bullrok'),
(18407,0,1,'That\'s the best reward we\'re going to be able to offer. Hopefully someone accepts the mission.',12,1,100,0,0,0,'Warden Bullrok'),
(18554,0,0,'You come into my house and threaten ME?  I think not!',12,0,100,0,0,0,'Sharth Voldoun'),
(18554,1,0,'All goes exceedingly well, my lord.  Testing of the smaller prototype at the Cenarion Thicket was a complete success.  The second bomb is being ritually fueled in the courtyard below even as we speak.  And, I\'ve sent a courier to Tuurem to bring the rest of the parts to us here.',12,0,100,0,0,0,'Sharth Voldoun'),
(18554,2,0,'You are satisfied?',12,0,100,0,0,0,'Sharth Voldoun'),
(18554,3,0,'I can assure you that we will not fail, my master.  I am personally overseeing every aspect of the construction, and I hold the final codes, myself.  Within a day\'s time, I will have the bomb detonated on those nearby pests.',12,0,100,2,0,0,'Sharth Voldoun'),
(18668,0,0,'No, you\'re wrong! We were the ones betrayed!',12,0,100,22,0,0,'Vaeron Kormar'),
(18668,1,0,'The Ranger-General of Silvermoon will be a loyal ally!',12,0,100,1,0,0,'Vaeron Kormar'),
(18668,2,0,'Blood will be true. We can trust in none but our own!',12,0,100,25,0,0,'Vaeron Kormar'),
(18668,3,0,'You call us traitors?',12,0,100,25,0,0,'Vaeron Kormar'),
(18669,0,0,'When have the dwarves ever been our friends?',12,0,100,11,0,0,'Terric Brightwind'),
(18669,1,0,'How are we to live without magic?',12,0,100,5,0,0,'Terric Brightwind'),
(18669,2,0,'Idealistic blather. Go back to your forests!',12,0,100,3,0,0,'Terric Brightwind'),
(18671,0,0,'You fool! The prince\'s minions were the very Forsaken we have now allied ourselves with, and now he has betrayed us!',12,0,100,5,0,0,'Priest Ennas'),
(18671,1,0,'A great blight lies across our land! It grows every day. Our need for magic weakens us, and will bring us to destruction, just as it has before!',12,0,100,25,0,0,'Priest Ennas'),
(18671,2,0,'But at what cost? You\'ve all been blinded. We have all been blinded. ',12,0,100,1,0,0,'Priest Ennas'),
(18671,3,0,'No, not savagery! Conscience. The excesses of our people will destroy us, and all that we have struggled to build.',12,0,100,1,0,0,'Priest Ennas'),
(18671,4,0,'We stand on the brink of destruction. We must reconsider this rash course of action.',12,0,100,5,0,0,'Priest Ennas'),
(18671,5,0,'Lend us your voices! Now is the time we must act to save our people.',12,0,100,1,0,0,'Priest Ennas'),
(18671,6,0,'Lor\'themar must hear us! We will not be silenced!',12,0,100,5,0,0,'Priest Ennas'),
(18671,7,0,'Lor\'themar has remade Silvermoon into something we may truly be proud of.',12,1,100,21,0,0,'Priest Ennas'),
(18671,8,0,'The magisters are wise and will plot a prosperous course for our future.',12,1,100,21,0,0,'Priest Ennas'),
(18698,0,0,'Intruder detected!  Neutralizing threat immediately!',12,0,100,0,0,0,'Ever-Core the Punisher'),
(18705,0,0,'%s faints.',16,0,100,0,0,0,'Mawg Grimshot'),
(18724,0,0,'The humans abandoned us in our darkest hour! Their prince himself led the assault on our lands.',12,0,100,25,0,0,'Melaya Tassier'),
(18724,1,0,'Look at the wonders of this city! This is magic.',12,0,100,5,0,0,'Melaya Tassier'),
(18724,2,0,'You would have us live like the savages!',12,0,100,5,0,0,'Melaya Tassier'),
(18756,0,0,'I, like, so don\'t get it...',12,0,100,1,0,0,'Haris Pilton'),
(18756,0,1,'Psshh... whatever.',12,0,100,1,0,0,'Haris Pilton'),
(18756,0,2,'That\'s hot.',12,0,100,1,0,0,'Haris Pilton'),
(18756,0,3,'That joke\'s hot.',12,0,100,1,0,0,'Haris Pilton'),
(18850,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Sunfury Guardsman'),
(18853,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Sunfury Bloodwarder'),
(18896,0,0,'Function: Intelligence Agents, Torturers',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,1,0,'The cruel sayaadi temptresses exemplify the subtler side of the Legion\'s nihilistic Crusade.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,2,0,'They revel in causing anguish and pain - and their murderous interrogations are the stuff of nightmares.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,3,0,'Felguard',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,4,0,'Species: Mo\'arg',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,5,0,'Affiliation: Burning Legion',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,6,0,'Function: Standard Soldiers',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,7,0,'Conscripted from the mo\'arg race, these warriors serve as the Legion\'s rank and file soldiers.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,8,0,'They are fearless and unwaveringly loyal to their master\'s godlike will.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,9,0,'Doomguard',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,10,0,'Species: Ered\'ruin',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,11,0,'Function: Shock Troops, Enforcers',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,12,0,'Powerful and deliberate, these winged aberrations are renowned across the cosmos for their brutality.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,13,0,'The Doomguard are utterly devoted to their Pit Lord masters and revel in the destruction of worlds.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,14,0,'Wrathguard',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,15,0,'Species: Eredar',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,16,0,'Function: Honor Guard',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,17,0,'Cunning and precise, the Wrathguard often protect the Legion\'s eredar masters.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,18,0,'Their skill in battle should never be underestimated.',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,19,0,'Succubus',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,20,0,'Species: Sayaad',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,21,0,'Shivarra',12,7,100,0,0,0,'Exodar Holographic Emitter'),
(18896,22,0,'Species: Shivarra',12,7,100,0,0,0,'Exodar Holographic Emitter'),
